"""Generate durable K54 report from actual locked results."""
import pathlib,json,hashlib,subprocess as sp
from k54_plan import D,T,ROOT,load,sha
B=pathlib.Path.home()/'Dropbox/personal_projects/quartz_kinetic54_cache_backups'
def main():
    a=load('AUDIT.json');s=load('SUMMARY.json');c=load('PARITY_LOCK.json')['counts'];b=load('BINARY_LOCK.json')
    rp=json.loads((T/'RAPFI_PARITY.json').read_text());st=json.loads((T/'STATS_INDEPENDENT.json').read_text())
    assert a['total']['games']==2896 and a['total']['episodes']==672 and c['target_roots']==56 and c['baseline_roots']==28 and c['hits']==117
    assert rp['counts']['requests']==24 and rp['counts']['old_nn']==rp['counts']['new_nn']
    old=D.parent/'quartz_kinetic53_reuse_20261127/NATIVE_IDENTITY.json';identity=json.loads(old.read_text())
    for q,digest in b['source_sha256'].items():assert sha(ROOT/q)==digest==hashlib.sha256(sp.check_output(['git','show',b['source_commit']+':'+q],cwd=ROOT)).hexdigest()
    assert sha(T/'mcts_demo')==b['binary_sha256']==sha(B/'mcts_demo') and b['old_binary_sha256']==identity['binary_sha256']
    assert sha(ROOT/'Cargo.lock')==b['cargo_lock_sha256']
    for q in s['locks']:assert load(q+'_LOCK.json')['binary']==b['binary_sha256']
    assert '658 passed; 0 failed; 89 ignored' in (T/'FULL_TEST.log').read_text()
    identity.update(k48_binary_sha256=identity['parent_parent_binary_sha256'],parent_parent_binary_sha256=identity['parent_binary_sha256'],binary_sha256=b['binary_sha256'],binary_bytes=b['bytes'],source_commit=b['source_commit'],source_sha256=b['source_sha256'],cargo_lock_sha256=b['cargo_lock_sha256'],rustc=b['rustc'],parent_binary_sha256=b['old_binary_sha256'],parent_native_identity_sha256=sha(old),full_test_raw_sha256=sha(T/'FULL_TEST.log'),scope='K54 native opt-in per-request exact evaluation cache, logical cap unchanged; K53 Rapfi target unchanged')
    (D/'NATIVE_IDENTITY.json').write_text(json.dumps(identity,indent=2,sort_keys=True)+'\n')
    n=s['nn']['all'];r=s['rapfi'];tc=a['total'];ct=a['counts'];u=s['uncached_replay']
    den=json.loads((T/'DENOM_DIAGNOSTIC.json').read_text())
    assert all(v['valid_NN']==8000 for panel in ('all','old','new','rapfi') for v in den[panel].values())
    assert den['replay']['finite_only_n']==7970

    lines=['# K54 native exact cache and independent Rapfi target confirmation','',
    '## Authority and theory',
    'Parent ba7594ce9a80eb156a0afc855f9ec45ffbd5f14e, remote equal,120-file restore verified. Reread 15f3a198 README/QUARTZ_THEORY and 7241ad0c THESIS. P1 posterior expected regret reduction per compute, P2 original A1, P3 emergent signatures. Exact native cache preserves logical count and trace under deterministic fixed input. Fair physical saving correction (b*hq-q*hb)/(b*(b-hb)); helps iff Q hit fraction>=B hit fraction, positive denominator required. Conditional second event after first no switch, not posterior optimum or additive local effect. Bellman form with unestablished transition law and shadow price. Literature SOURCES.md. Rational checks48300 fair-cache,6561 trace,18 conditional; Wolfram correction/inequality/telescoping. R10 c0aedfc0399d1b23e928661c83bd4941e1b9fc3d. Initial multi-plugin call timed out, subsequent separate searches and CAS succeeded.',
    '## Native implementation and parity',
    f"Native source {b['source_commit']}, SHA {b['binary_sha256']}, {b['rustc']}. Opt-in cache:true, exact full key (a,b,p,ordered legal), request-local, no cross-model cache; ev.calls logical, physical IPC id only on miss, logical trace all queries. Native cache_receipt physical/logical, hit indices and root counts; experiment wrapper normalizes historical physical_nn field to logical root count for old audit, actual_nn authoritative physical count. Focused actual red-green, release build and full Rust658/0/89. 56 target and28 B32 archived roots exact old/new/cache parity: logical2310 physical2193 hits117, old and new uncached2310 each. Rapfi unchanged code and old/new parity {rp['counts']}. No native subagent tools, GPU not exposed, no new training, generic parallel integration or main merge. Scheduling: "+(T/'SCHEDULE.log').read_text().strip()+'.',
    '## Fresh NN games with symmetric cache',
    '48 fresh families x7 fixed models x2 colors x3 separate Q-v-B32 policies=2016 actual games. CONTROL fixed20; COLD first eligible target; CONDITIONAL exactly one additional eligible root iff first target kept incumbent. All Q and B searches native cached; no prohibited matchups. Family bootstrap8000. Physical and logical count estimates on same trajectories, not independent games.',
    '|arm|W/D/L|score|logical NN saving|physical NN saving|physical lower95|CPU saving|Q/B cache hits|','|---|---|---:|---:|---:|---:|---:|---|']
    for arm,q in n['arms'].items():
        w=q['physical']['counts'];v=q['physical']['metrics'];l=q['physical']['lower95'];cc=q['counts'];lines.append(f"|{arm}|{w['wins']}/{w['draws']}/{w['losses']}|{v['score']:.9f}|{q['logical']['metrics']['NN_reduction']:.9f}|{v['NN_reduction']:.9f}|{l['NN_reduction']:.9f}|{v['CPU_reduction']:.9f}|{cc['Q_hits']}/{cc['B_hits']}|")
    lines.append('Cache hit rates and all per-move ratios in SUMMARY.json; baseline and Quartz both count physical requests, no accounting advantage from asymmetric cache. CPU measurements from actual cached arms; logical cost comparison does not imply uncached timing.')
    lines+=['','|contrast|episodes|improved/worsened|score gain|physical local NN|logical local NN|net Q|net total|','|---|---:|---|---:|---:|---:|---:|---:|']
    for arm,q in n['pairs'].items():
        v=q['counts'];lines.append(f"|{arm}|{v['n']}|{v['improved']}/{v['worsened']}|{v['delta2']/2:g}|{v['local_nn']}|{q['logical_extra_total']}|{v['delta_Q']}|{v['delta_total']}|")
    for arm,q in n['pairs'].items():
        lines.append(f"{arm} paired score effect {q['metrics']['tau']:.10f}, CI {q['CI']['tau']}; local ratio {q['ratio']['local_nn']}; signed net ratio {q['ratio']['delta_total']}.")
    lines.append(f"Conditional event histogram {s['conditional_events']}, diagnostics {s['conditional_diagnostic']}; no-repeat trajectories equal COLD. Panel effects old/new {s['nn']['old']['pairs']['conditional']['CI']['tau']} / {s['nn']['new']['pairs']['conditional']['CI']['tau']}. No automatic adoption of conditional policy. COLD retains K52 scientific admission; new smaller sample separate.")
    lines+=['','## Whole-game uncached replay',
      f"Actual112 COLD vs same B32 games repeated without cache on first8 frozen families, all histories/scores/logical semantic receipts equal to cached games. Not additional independent families. Cached counts {u['cached']['counts']}; uncached score {u['uncached']['metrics']['score']}, logical NN reduction {u['uncached']['metrics']['NN_reduction']}, cached physical NN reduction {u['cached']['physical']['metrics']['NN_reduction']}; physical contrast {u['physical_contrast']['NN_reduction']}. Timing contrasts descriptive only, runtime/load/order not randomized across modes.",
      '## Prospective Rapfi confirmation',
      '192 fresh outer families, paired colors, Q96 and frozen K53 TARGET each separately vs B128=768 actual games. No tuning or sample stopping. Primary joint target gates lower95 score>=.45, NN>=.30, CPU positive. Paired superiority exploratory.',
      '|arm|W/D/L|score|NN/move saving|CPU/move saving|score lower95|NN lower95|gate|','|---|---|---:|---:|---:|---:|---:|---|']
    for arm,q in r['arms'].items():
        w=q['counts'];v=q['metrics'];l=q['lower95'];lines.append(f"|{arm}|{w['wins']}/{w['draws']}/{w['losses']}|{v['score']:.9f}|{v['NN_reduction']:.9f}|{v['CPU_reduction']:.9f}|{l['score']:.9f}|{l['NN_reduction']:.9f}|{q['gate']}|")
    lines.append(f"Independent target confirmed={r['confirmed']}; paired effect {r['paired']['metrics']['tau']} CI {r['paired']['CI']['tau']}; counts {r['paired']['counts']}; local score/call {r['paired']['ratio']['local_nn']}; independent standard-library target score and saving CI {st['rapfi']['T']['score']} / {st['rapfi']['T']['NN_reduction']}. No claim superiority unless paired CI supports it. Outer synthetic distribution only; no human opening universal claim.")
    lines.append(f"Denominator diagnostic: all primary NN and Rapfi panel draws (8000 each) have positive B NN and move denominators. Reused analysis emitted 0/0 warnings for30 of8000 eight-family replay draws with zero B NN (certified-only samples). Do not interpret the original replay ratio CI as unqualified. Finite-only paired NN-saving delta CI from7970 valid draws {den['replay']['finite_only_delta_NN_CI']}; conditioning on positive denominator is descriptive only. Point ratios and full semantic replay unaffected. Exact diagnostic counts {json.dumps(den,sort_keys=True)}. Diagnostic constructed family counts and resampled using the same frozen seed/index sequence, no outcome-based exclusion of games.")
    parity=c['old_nn']+c['new_uncached']+c['physical']+rp['counts']['old_nn']+rp['counts']['new_nn']
    physical=tc['physical']+tc['nn'];logical=tc['logical']+tc['nn']
    lines+=['','## Independent audit and next',
      f"Actual {tc['games']} recorded games (2784 distinct primary and112 same-family uncached repeats), {tc['moves']} moves, {physical} physical game calls, {logical} logical calls; {parity} separate actual parity calls. Cache hits {ct.get('cache_hits',0)}, root {ct.get('cache_root_hits',0)}, target {ct.get('cache_target_hits',0)}. Proof receipts {ct.get('proof_receipts',0)}, bounds {ct.get('independent_bound_cells',0)}, certificates {ct.get('independent_partial_cert',0)}, proof queries {ct.get('proof_queries',0)}, votes {ct.get('votes',0)}, cold child receipts {ct.get('child_receipts',0)}, Rapfi child receipts {ct.get('rapfi_children',0)}, wave receipts {ct.get('wave_receipts',0)}, waves {ct.get('waves',0)}. Natural exact {a['natural_exact']}. Independent integer coordinate and stdlib family8000 resampling, per-request key arithmetic. No exhaustive independent NN architecture validation.",
      ('K55 Rapfi: independent outer gate passed, freeze scoped TARGET and test independent compact/other distributions and tactical hard cases. ' if r['confirmed'] else 'K55 Rapfi: independent outer gate failed; preserve K53 exploratory success, diagnose quality/cost and predecision root features; do not retune using this holdout. ')+ 'NN: native exact cache preserved tested semantics; next integrate cache into generic engine only after full-input/model/generation identity and same-cache baseline parity, extend cache lifetime as separate resource experiment. Conditional second event needs calibrated marginal utility rather than no-switch alone; retain K52 single cold reference. P1 posterior optimization, P2 original A1 and P3 GM signatures remain open. Local Dropbox cloud sync NOT_VERIFIED.']
    (D/'REPORT.md').write_text('\n'.join(x.rstrip() for x in lines)+'\n')
    with (D/'ORIGIN_WATCHDOG.md').open('a') as w:w.write(f"\n## Outcome\nNative cache exact84 roots and112 whole-game matched uncached repeats. Physical fair-cache results {[(k,v['physical']['metrics']['NN_reduction']) for k,v in n['arms'].items()]}. Conditional second effect {n['pairs']['conditional']['metrics']['tau']} CI {n['pairs']['conditional']['CI']['tau']}; Rapfi frozen TARGET independent outer confirmed={r['confirmed']}, gate={r['arms']['T']['gate']}. No posterior optimality or original A1/P3 substitution; fixed thresholds exploratory.\n")
    print('FINAL_REPORT',r['confirmed'],tc,'physical',physical,'logical',logical,'parity',parity,flush=True)
if __name__=='__main__':main()
